css:
* { margin: 0px; padding: 0px; box-sizing: border-box; }
.snap-body { min-height: 810px; font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Inter, Roboto, sans-serif; background: rgb(9, 9, 11); color: rgb(250, 250, 250); line-height: 1.5; -webkit-font-smoothing: antialiased; overflow-x: hidden; display: block; padding: 0px; }
.snap-body::before { content: ""; position: fixed; top: -220px; left: 50%; transform: translateX(-50%); width: 900px; height: 460px; background: radial-gradient(circle, rgba(255, 0, 0, 0.055) 0%, transparent 70%); pointer-events: none; z-index: 0; }
.app { width: 820px; min-height: 520px; display: flex; background: rgb(13, 13, 15); border: 1px solid rgba(255, 255, 255, 0.06); border-radius: 18px; overflow: hidden; position: relative; z-index: 1; box-shadow: rgba(0, 0, 0, 0.45) 0px 24px 64px; animation: 0.5s cubic-bezier(0.16, 1, 0.3, 1) 0s 1 normal both running appIn; }
@keyframes appIn { 
  0% { opacity: 0; transform: translateY(10px); }
  100% { opacity: 1; transform: translateY(0px); }
}
.sidebar { width: 208px; flex-shrink: 0; border-right: 1px solid rgba(255, 255, 255, 0.06); padding: 20px 12px; display: flex; flex-direction: column; }
.brand { display: flex; align-items: center; gap: 10px; padding: 4px 8px 20px; }
.brand img { width: 30px; height: 30px; border-radius: 8px; flex-shrink: 0; }
.brand-name { font-size: 13px; font-weight: 600; letter-spacing: -0.01em; color: rgb(250, 250, 250); line-height: 1.2; }
.brand-ver { font-size: 11px; color: rgb(82, 82, 91); margin-top: 1px; }
.nav { display: flex; flex-direction: column; gap: 2px; }
.nav-item { position: relative; display: flex; align-items: center; gap: 10px; width: 100%; padding: 9px 12px; background: transparent; border-width: medium; border-style: none; border-color: currentcolor; border-image: none; border-radius: 8px; color: rgb(161, 161, 170); font-size: 13px; font-weight: 500; font-family: inherit; text-align: left; cursor: pointer; transition: background 0.18s, color 0.18s; }
.nav-item svg { width: 16px; height: 16px; fill: currentcolor; flex-shrink: 0; opacity: 0.9; }
.nav-item:hover { background: rgba(255, 255, 255, 0.04); color: rgb(250, 250, 250); }
.nav-item.active { background: rgba(255, 255, 255, 0.07); color: rgb(250, 250, 250); }
.nav-item.active::before { content: ""; position: absolute; left: 0px; top: 50%; transform: translateY(-50%); width: 3px; height: 16px; border-radius: 0px 3px 3px 0px; background: rgb(239, 68, 68); }
.sidebar-foot { margin-top: auto; padding: 14px 8px 2px; font-size: 11px; color: rgb(63, 63, 70); letter-spacing: 0.02em; }
.content { flex: 1 1 0%; min-width: 0px; padding: 28px 30px 32px; }
.pane { display: none; }
.pane.active { display: block; animation: 0.4s cubic-bezier(0.16, 1, 0.3, 1) 0s 1 normal both running fadeUp; }
.pane-head { margin-bottom: 20px; }
.pane-title { font-size: 16px; font-weight: 600; letter-spacing: -0.02em; color: rgb(250, 250, 250); }
.pane-sub { font-size: 12.5px; color: rgb(113, 113, 122); margin-top: 3px; }
@keyframes fadeUp { 
  0% { opacity: 0; transform: translateY(6px); }
  100% { opacity: 1; transform: translateY(0px); }
}
@keyframes spin { 
  0% { transform: rotate(0deg); }
  100% { transform: rotate(360deg); }
}
.model-card { background: rgb(24, 24, 27); border: 1px solid rgba(255, 255, 255, 0.06); border-radius: 14px; padding: 20px; margin-bottom: 12px; position: relative; overflow: hidden; transition: border-color 0.3s, box-shadow 0.3s; }
.model-card:hover { border-color: rgba(255, 255, 255, 0.1); box-shadow: rgba(0, 0, 0, 0.3) 0px 8px 32px; }
.model-card::before { content: ""; position: absolute; top: 0px; left: 0px; right: 0px; height: 1px; background: linear-gradient(90deg, transparent, rgba(255, 255, 255, 0.06), transparent); }
.card-header { display: flex; align-items: center; gap: 12px; margin-bottom: 18px; }
.model-icon { width: 36px; height: 36px; display: flex; align-items: center; justify-content: center; flex-shrink: 0; position: relative; }
.model-icon svg { width: 22px; height: 22px; fill: currentcolor; }
.model-icon.openai { color: rgb(250, 250, 250); }
.model-info { flex: 1 1 0%; }
.model-name { font-size: 14px; font-weight: 600; color: rgb(250, 250, 250); letter-spacing: -0.01em; }
.model-desc { font-size: 12px; color: rgb(82, 82, 91); margin-top: 1px; }
.status-badge { font-size: 11px; font-weight: 500; padding: 3px 8px; border-radius: 20px; letter-spacing: 0.02em; transition: 0.3s; }
.status-badge.configured { background: rgba(34, 197, 94, 0.1); color: rgb(74, 222, 128); border: 1px solid rgba(34, 197, 94, 0.2); }
.status-badge.not-configured { background: rgba(113, 113, 122, 0.1); color: rgb(113, 113, 122); border: 1px solid rgba(113, 113, 122, 0.2); }
.status-badge.invalid { background: rgba(239, 68, 68, 0.1); color: rgb(239, 68, 68); border: 1px solid rgba(239, 68, 68, 0.2); }
.input-group { position: relative; margin-bottom: 12px; }
.input-group label { display: block; font-size: 12px; font-weight: 500; color: rgb(161, 161, 170); margin-bottom: 6px; letter-spacing: 0.02em; }
.input-wrapper { position: relative; display: flex; align-items: center; }
.input-wrapper input { width: 100%; padding: 10px 40px 10px 12px; background: rgb(9, 9, 11); color: rgb(250, 250, 250); border: 1px solid rgba(255, 255, 255, 0.08); border-radius: 8px; font-size: 13px; font-family: "SF Mono", "Fira Code", "Cascadia Code", monospace; letter-spacing: 0.03em; outline: none; transition: border-color 0.2s, box-shadow 0.2s; }
.input-wrapper input::placeholder { color: rgb(63, 63, 70); font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Inter, Roboto, sans-serif; letter-spacing: 0px; }
.input-wrapper input:focus { border-color: rgba(255, 255, 255, 0.15); box-shadow: rgba(255, 255, 255, 0.03) 0px 0px 0px 3px; }
.input-wrapper input.secured { letter-spacing: 0.15em; }
.input-wrapper select { width: 100%; padding: 10px 12px; background: url("data:image/svg+xml;utf8,<svg fill=\"%23a1a1aa\" viewBox=\"0 0 24 24\" xmlns=\"http://www.w3.org/2000/svg\"><path d=\"M7 10l5 5 5-5z\"/></svg>") right 10px center no-repeat rgb(9, 9, 11); color: rgb(250, 250, 250); border: 1px solid rgba(255, 255, 255, 0.08); border-radius: 8px; font-size: 13px; outline: none; transition: border-color 0.2s, box-shadow 0.2s; appearance: none; }
.input-wrapper select:focus { border-color: rgba(255, 255, 255, 0.15); box-shadow: rgba(255, 255, 255, 0.03) 0px 0px 0px 3px; }
.input-wrapper select:disabled { opacity: 0.5; cursor: not-allowed; }
.toggle-visibility { position: absolute; right: 8px; width: 28px; height: 28px; display: flex; align-items: center; justify-content: center; background: transparent; border-width: medium; border-style: none; border-color: currentcolor; border-image: none; border-radius: 6px; cursor: pointer; color: rgb(82, 82, 91); transition: color 0.2s, background 0.2s; padding: 0px; }
.toggle-visibility:hover { color: rgb(161, 161, 170); background: rgba(255, 255, 255, 0.05); }
.toggle-visibility svg { width: 16px; height: 16px; fill: currentcolor; }
.save-btn { width: 100%; padding: 9px 16px; background: rgba(255, 255, 255, 0.06); color: rgb(212, 212, 216); border: 1px solid rgba(255, 255, 255, 0.08); border-radius: 8px; font-size: 13px; font-weight: 500; font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Inter, Roboto, sans-serif; cursor: pointer; transition: 0.2s; position: relative; overflow: hidden; }
.save-btn:hover { background: rgba(255, 255, 255, 0.1); border-color: rgba(255, 255, 255, 0.12); color: rgb(250, 250, 250); }
.save-btn:active { transform: scale(0.99); }
.save-btn.saving { background: rgba(34, 197, 94, 0.1); border-color: rgba(34, 197, 94, 0.3); color: rgb(74, 222, 128); pointer-events: none; }
.save-btn .btn-content { display: flex; align-items: center; justify-content: center; gap: 6px; transition: opacity 0.2s; }
.save-btn .btn-content svg { width: 14px; height: 14px; fill: currentcolor; }
.toast { position: fixed; bottom: 20px; left: 50%; transform: translateX(-50%) translateY(20px); background: rgb(39, 39, 42); color: rgb(250, 250, 250); padding: 8px 16px; border-radius: 8px; font-size: 13px; font-weight: 500; border: 1px solid rgba(255, 255, 255, 0.08); box-shadow: rgba(0, 0, 0, 0.4) 0px 8px 32px; opacity: 0; transition: 0.3s cubic-bezier(0.16, 1, 0.3, 1); pointer-events: none; z-index: 100; display: flex; align-items: center; gap: 6px; }
.toast.show { opacity: 1; transform: translateX(-50%) translateY(0px); }
.toast svg { width: 14px; height: 14px; fill: rgb(74, 222, 128); }
.info-banner { display: flex; align-items: flex-start; gap: 10px; background: rgb(24, 24, 27); border: 1px solid rgba(255, 255, 255, 0.06); border-radius: 12px; padding: 12px 14px; margin-bottom: 16px; transition: border-color 0.3s; }
.info-banner.ready { border-color: rgba(34, 197, 94, 0.2); background: rgba(34, 197, 94, 0.04); }
.banner-icon { flex-shrink: 0; margin-top: 1px; }
.banner-icon svg { width: 18px; height: 18px; fill: rgb(113, 113, 122); }
.info-banner.ready .banner-icon svg { fill: rgb(74, 222, 128); }
.info-banner p { font-size: 12.5px; color: rgb(161, 161, 170); line-height: 1.5; }
.info-banner p strong { color: rgb(250, 250, 250); font-weight: 600; }
.action-row { display: flex; gap: 8px; align-items: stretch; }
.action-row .save-btn { flex: 1 1 0%; }
.remove-btn { padding: 9px 14px; background: transparent; color: rgb(113, 113, 122); border: 1px solid rgba(255, 255, 255, 0.08); border-radius: 8px; font-size: 13px; font-weight: 500; font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Inter, Roboto, sans-serif; cursor: pointer; transition: 0.2s; white-space: nowrap; }
.remove-btn:hover { color: rgb(239, 68, 68); border-color: rgba(239, 68, 68, 0.3); background: rgba(239, 68, 68, 0.06); }
.remove-btn[hidden] { display: none; }
.key-hint { font-size: 11px; color: rgb(113, 113, 122); font-family: "SF Mono", "Fira Code", "Cascadia Code", monospace; letter-spacing: 0.04em; margin: -2px 0px 12px; display: flex; align-items: center; gap: 6px; }
.key-hint::before { content: ""; width: 6px; height: 6px; border-radius: 50%; background: rgb(74, 222, 128); box-shadow: rgba(74, 222, 128, 0.6) 0px 0px 6px; flex-shrink: 0; }
.key-hint[hidden] { display: none; }
.modal-actions { display: flex; justify-content: flex-end; gap: 12px; margin-top: 32px; }
.command-palette { width: 440px; padding: 0px; background: rgb(24, 24, 27); border: 1px solid rgba(255, 255, 255, 0.08); box-shadow: rgba(0, 0, 0, 0.5) 0px 20px 40px; }
.command-palette .modal-header { padding: 16px 20px; border-bottom: 1px solid rgba(255, 255, 255, 0.06); margin-bottom: 0px; }
.command-search { width: 100%; background: transparent; border-width: medium medium 1px; border-style: none none solid; border-color: currentcolor currentcolor rgba(255, 255, 255, 0.08); border-image: none; color: rgb(250, 250, 250); font-size: 15px; padding: 16px 20px; outline: none; }
.command-search::placeholder { color: rgb(113, 113, 122); }
.command-list { max-height: 320px; overflow-y: auto; padding: 8px; }
.command-item { display: flex; align-items: center; gap: 12px; padding: 12px 16px; border-radius: 8px; cursor: pointer; transition: background 0.15s, color 0.15s; color: rgb(212, 212, 216); }
.command-item:hover { background: rgba(255, 255, 255, 0.05); color: rgb(250, 250, 250); }
.command-item.active { background: rgba(59, 130, 246, 0.15); color: rgb(96, 165, 250); }
.command-item-icon { width: 20px; height: 20px; display: flex; align-items: center; justify-content: center; }
.command-item-icon svg { width: 100%; height: 100%; fill: currentcolor; }
.command-item-name { flex: 1 1 0%; font-size: 14px; font-weight: 500; }
.selector-btn { margin-top: 16px; display: inline-flex; align-items: center; justify-content: space-between; gap: 12px; padding: 10px 16px; background: rgb(24, 24, 27); border: 1px solid rgba(255, 255, 255, 0.1); border-radius: 8px; color: rgb(250, 250, 250); font-size: 14px; font-weight: 500; cursor: pointer; transition: 0.2s; min-width: 200px; }
.selector-btn:hover { background: rgb(39, 39, 42); border-color: rgba(255, 255, 255, 0.2); }
.selector-btn-content { display: flex; align-items: center; gap: 10px; }
.selector-btn-icon { width: 18px; height: 18px; display: flex; align-items: center; justify-content: center; color: rgb(161, 161, 170); }
.selector-btn-icon svg { width: 100%; height: 100%; fill: currentcolor; }
.help { margin-top: 24px; border-top: 1px solid rgba(255, 255, 255, 0.06); padding-top: 16px; }
.help-toggle { width: 100%; display: flex; align-items: center; gap: 8px; background: transparent; border-width: medium; border-style: none; border-color: currentcolor; border-image: none; padding: 2px 0px; cursor: pointer; color: rgb(161, 161, 170); font-size: 12.5px; font-weight: 500; font-family: inherit; transition: color 0.2s; }
.help-toggle:hover { color: rgb(250, 250, 250); }
.help-toggle-label { display: flex; align-items: center; gap: 7px; flex: 1 1 0%; text-align: left; }
.help-toggle-label svg { width: 14px; height: 14px; fill: currentcolor; opacity: 0.7; flex-shrink: 0; }
.help-chevron { width: 16px; height: 16px; fill: rgb(82, 82, 91); transition: transform 0.3s cubic-bezier(0.16, 1, 0.3, 1); flex-shrink: 0; }
.help-toggle[aria-expanded="true"] .help-chevron { transform: rotate(90deg); }
.free-badge { font-size: 10px; font-weight: 600; letter-spacing: 0.04em; text-transform: uppercase; color: rgb(251, 191, 36); background: rgba(251, 191, 36, 0.1); border: 1px solid rgba(251, 191, 36, 0.2); padding: 2px 7px; border-radius: 20px; flex-shrink: 0; }
.help-body { display: grid; grid-template-rows: 0fr; transition: grid-template-rows 0.35s cubic-bezier(0.16, 1, 0.3, 1); }
.help-body.open { grid-template-rows: 1fr; }
.help-body-inner { overflow: hidden; min-height: 0px; }
.help-steps { list-style: none; counter-reset: step 0; margin: 12px 0px 0px; padding: 0px; }
.help-steps li { counter-increment: step 1; position: relative; padding-left: 26px; margin-bottom: 8px; font-size: 12.5px; color: rgb(161, 161, 170); line-height: 1.5; }
.help-steps li::before { content: counter(step); position: absolute; left: 0px; top: 0px; width: 18px; height: 18px; border-radius: 50%; background: rgba(255, 255, 255, 0.06); border: 1px solid rgba(255, 255, 255, 0.08); color: rgb(212, 212, 216); font-size: 10px; font-weight: 600; display: flex; align-items: center; justify-content: center; font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif; }
.help-steps li strong { color: rgb(250, 250, 250); font-weight: 600; }
.help-steps a { color: rgb(59, 130, 246); text-decoration: none; }
.help-steps a:hover { text-decoration: underline; }
.help-note { font-size: 11.5px; color: rgb(113, 113, 122); margin: 2px 0px 12px; padding-left: 26px; line-height: 1.45; }
.get-key-btn { display: inline-flex; align-items: center; gap: 6px; padding: 8px 14px; background: rgba(255, 255, 255, 0.06); border: 1px solid rgba(255, 255, 255, 0.1); border-radius: 8px; color: rgb(250, 250, 250); font-size: 12.5px; font-weight: 500; text-decoration: none; transition: 0.2s; }
.get-key-btn:hover { background: rgba(255, 255, 255, 0.1); border-color: rgba(255, 255, 255, 0.15); transform: translateY(-1px); }
.get-key-btn svg { width: 13px; height: 13px; fill: currentcolor; }
.add-provider { display: flex; align-items: center; gap: 10px; width: 100%; padding: 13px 16px; margin-bottom: 4px; background: transparent; border: 1px dashed rgba(255, 255, 255, 0.12); border-radius: 14px; color: rgb(82, 82, 91); font-size: 13px; font-weight: 500; font-family: inherit; text-align: left; transition: 0.2s; cursor: pointer !important; }
.add-provider:hover { background: rgba(255, 255, 255, 0.04); border-color: rgba(255, 255, 255, 0.2); color: rgb(250, 250, 250); }
.add-provider svg { width: 16px; height: 16px; fill: currentcolor; flex-shrink: 0; }
.add-provider .coming-soon { margin-left: auto; font-size: 10px; font-weight: 600; letter-spacing: 0.05em; text-transform: uppercase; color: rgb(113, 113, 122); background: rgba(255, 255, 255, 0.05); border: 1px solid rgba(255, 255, 255, 0.08); padding: 2px 8px; border-radius: 20px; }
.privacy-note { display: flex; align-items: center; gap: 6px; font-size: 11px; color: rgb(82, 82, 91); margin: 16px 2px 0px; line-height: 1.4; }
.privacy-note svg { width: 14px; height: 14px; fill: currentcolor; }
.modal-overlay { position: fixed; inset: 0px; background: rgba(0, 0, 0, 0.6); display: flex; justify-content: center; align-items: center; z-index: 100; backdrop-filter: blur(4px); }
.modal-overlay[hidden] { display: none; }
.modal-content { background: rgb(9, 9, 11); border: 1px solid rgba(255, 255, 255, 0.1); border-radius: 12px; width: 100%; max-width: 440px; overflow: hidden; box-shadow: rgba(0, 0, 0, 0.5) 0px 10px 40px; }
.modal-header { padding: 16px 20px; border-bottom: 1px solid rgba(255, 255, 255, 0.05); display: flex; justify-content: space-between; align-items: center; }
.modal-header h3 { margin: 0px; font-size: 16px; font-weight: 500; color: rgb(250, 250, 250); }
.close-modal { background: none; border-width: medium; border-style: none; border-color: currentcolor; border-image: none; color: rgb(161, 161, 170); cursor: pointer; padding: 4px; display: flex; border-radius: 4px; transition: 0.2s; }
.close-modal:hover { background: rgba(255, 255, 255, 0.1); color: rgb(250, 250, 250); }
.close-modal svg { width: 20px; height: 20px; fill: currentcolor; }
.modal-body { padding: 20px; display: flex; flex-direction: column; gap: 16px; }
.modal-footer { padding: 16px 20px; border-top: 1px solid rgba(255, 255, 255, 0.05); display: flex; justify-content: flex-end; }
.modal-footer .save-btn { width: auto; padding: 8px 16px; }
.setting-section { background: rgb(24, 24, 27); border: 1px solid rgba(255, 255, 255, 0.06); border-radius: 14px; padding: 16px 20px; margin-bottom: 12px; }
.setting-header { margin-bottom: 12px; }
.setting-title { display: block; font-size: 14px; font-weight: 600; color: rgb(250, 250, 250); letter-spacing: -0.01em; }
.setting-sub { display: block; font-size: 12px; color: rgb(82, 82, 91); margin-top: 2px; }
.segmented { display: flex; gap: 4px; background: rgb(9, 9, 11); border: 1px solid rgba(255, 255, 255, 0.08); border-radius: 10px; padding: 4px; }
.segmented-option { flex: 1 1 0%; padding: 8px 0px; background: transparent; color: rgb(161, 161, 170); border-width: medium; border-style: none; border-color: currentcolor; border-image: none; border-radius: 7px; font-size: 13px; font-weight: 500; font-family: inherit; cursor: pointer; transition: background 0.2s, color 0.2s; }
.segmented-option:hover { color: rgb(250, 250, 250); }
.segmented-option[aria-checked="true"] { background: rgba(255, 255, 255, 0.08); color: rgb(250, 250, 250); }
.segmented-option:disabled { opacity: 0.38; cursor: not-allowed; }
.segmented-option:disabled:hover { color: rgb(161, 161, 170); }
.stats-row { display: flex; gap: 12px; margin-bottom: 12px; }
.stat-card { flex: 1 1 0%; min-width: 0px; background: rgb(24, 24, 27); border: 1px solid rgba(255, 255, 255, 0.06); border-radius: 14px; padding: 20px; text-align: center; }
.stat-value { font-size: 28px; font-weight: 600; letter-spacing: -0.02em; color: rgb(250, 250, 250); line-height: 1.1; }
.stat-label { display: flex; align-items: center; justify-content: center; gap: 5px; font-size: 12.5px; color: rgb(113, 113, 122); margin-top: 6px; }
.info-btn { position: relative; display: inline-flex; align-items: center; justify-content: center; cursor: help; color: rgb(82, 82, 91); transition: color 0.2s; outline: none; }
.info-btn:hover, .info-btn:focus-visible { color: rgb(161, 161, 170); }
.info-btn svg { width: 14px; height: 14px; fill: currentcolor; display: block; }
.info-tip { position: absolute; bottom: calc(100% + 8px); left: 50%; transform: translateX(-50%) translateY(4px); width: 220px; background: rgb(39, 39, 42); color: rgb(212, 212, 216); border: 1px solid rgba(255, 255, 255, 0.08); border-radius: 8px; padding: 8px 10px; font-size: 11.5px; font-weight: 400; line-height: 1.45; text-align: left; box-shadow: rgba(0, 0, 0, 0.4) 0px 8px 32px; opacity: 0; pointer-events: none; transition: opacity 0.2s, transform 0.2s; z-index: 50; }
.info-btn:hover .info-tip, .info-btn:focus-visible .info-tip, .info-btn:focus-within .info-tip { opacity: 1; transform: translateX(-50%) translateY(0px); }
.about-list { display: flex; flex-direction: column; gap: 14px; }
.about-row { display: flex; flex-direction: column; gap: 3px; }
.about-row-label { font-size: 11px; font-weight: 600; letter-spacing: 0.04em; text-transform: uppercase; color: rgb(113, 113, 122); }
.about-row-value { font-size: 12.5px; color: rgb(161, 161, 170); line-height: 1.5; }
.made-by { text-align: center; padding: 24px 20px; }
.made-by-line { font-size: 15px; font-weight: 500; color: rgb(250, 250, 250); }
.made-by-line .heart { color: rgb(239, 68, 68); font-style: normal; }
.made-by-sub { font-size: 12.5px; color: rgb(113, 113, 122); margin-top: 6px; margin-bottom: 16px; line-height: 1.5; }
.contact-link { display: inline-block; font-size: 13.5px; font-weight: 500; color: rgb(250, 250, 250); text-decoration: none; padding: 8px 16px; border: 1px solid rgba(255, 255, 255, 0.1); border-radius: 10px; transition: background 0.15s, border-color 0.15s; }
.contact-link:hover { background: rgba(239, 68, 68, 0.1); border-color: rgba(239, 68, 68, 0.4); }
